package com.novacommerce.order.infrastructure.persistence; import com.novacommerce.order.domain.order.*; import java.time.Instant; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface OrderRepository extends JpaRepository<CustomerOrder,UUID>{Optional<CustomerOrder>findByOwnerIdAndIdempotencyKey(UUID owner,String key);Optional<CustomerOrder>findByIdAndOwnerId(UUID id,UUID owner);Page<CustomerOrder>findByOwnerIdOrderByCreatedAtDesc(UUID owner,Pageable page);@Query("select o from CustomerOrder o where (o.status=com.novacommerce.order.domain.order.OrderStatus.PENDING_INVENTORY and o.createdAt<:pendingBefore) or (o.status=com.novacommerce.order.domain.order.OrderStatus.AWAITING_PAYMENT and o.reservationExpiresAt<=:now) order by o.createdAt")List<CustomerOrder>findExpirable(@Param("pendingBefore")Instant pendingBefore,@Param("now")Instant now,Pageable page);}
